-- ISS-11212 (PLN-2120 Step 2): the comment contract core. Generated by
-- `prisma migrate dev --create-only`, then hand-edited where Prisma cannot
-- express the change. Each hand-written part is marked HAND-WRITTEN below:
--   1. `comments.body_format` is added NULLABLE, backfilled from the stored
--      body, and only then SET NOT NULL. Prisma's generated `ADD COLUMN ... NOT
--      NULL` without a default fails on any non-empty table.
--   2. The single-target CHECK on `comment_sync_states`. Prisma has no syntax
--      for a CHECK constraint.
--   3. The trace anchor move out of `comment_threads.metadata`.
--   4. Two BEFORE INSERT triggers that apply rules 1 and 3 to rows an api
--      bundle built before this migration still inserts (see below).
-- The two `comment_sync_states` uniques also carry `IF NOT EXISTS` and an
-- `index-lock-ok` marker, which `scripts/lint/check-destructive-migrations.ts`
-- requires for a plain index build; their INDEX_LOCK_ALLOWLIST entries are in
-- `scripts/lint/destructive-migrations/index-lock-allowlist.ts`.

-- CreateEnum
CREATE TYPE "CommentAnchorState" AS ENUM ('ANCHORED', 'MOVED', 'OUTDATED', 'ORPHANED');

-- CreateEnum
CREATE TYPE "CommentBodyFormat" AS ENUM ('RICH_V1', 'MARKDOWN', 'LIVEBLOCKS_V1');

-- CreateEnum
CREATE TYPE "CommentSyncProvider" AS ENUM ('DESKTOP', 'GITHUB', 'LIVEBLOCKS');

-- CreateEnum
CREATE TYPE "CommentSyncDirection" AS ENUM ('INBOUND', 'OUTBOUND', 'BOTH');

-- CreateEnum
CREATE TYPE "CommentSyncStatus" AS ENUM ('SYNCED', 'PENDING', 'FAILED', 'ABANDONED');

-- AlterTable
ALTER TABLE "comment_threads" ADD COLUMN     "anchor" JSONB,
ADD COLUMN     "anchor_state" "CommentAnchorState",
ADD COLUMN     "revision" INTEGER NOT NULL DEFAULT 0;

-- AlterTable (HAND-WRITTEN 1: nullable here, SET NOT NULL after the backfill)
ALTER TABLE "comments" ADD COLUMN     "body_format" "CommentBodyFormat",
ADD COLUMN     "revision" INTEGER NOT NULL DEFAULT 0;

-- CreateTable
CREATE TABLE "comment_sync_states" (
    "id" UUID NOT NULL,
    "organization_id" UUID NOT NULL,
    "thread_id" UUID,
    "comment_id" UUID,
    "provider" "CommentSyncProvider" NOT NULL,
    "direction" "CommentSyncDirection" NOT NULL,
    "state" "CommentSyncStatus" NOT NULL,
    "synced_revision" INTEGER,
    "provider_updated_at" TIMESTAMP(3),
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "last_error_code" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "comment_sync_states_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
-- index-lock-ok(comment_sync_states): table is created empty in this same migration so both target uniques build against zero rows with no concurrent writer, and CONCURRENTLY cannot be mixed with the table-creation DDL Prisma wraps in one transaction
CREATE UNIQUE INDEX IF NOT EXISTS "comment_sync_states_thread_id_provider_direction_key" ON "comment_sync_states"("thread_id", "provider", "direction");

-- CreateIndex
-- index-lock-ok(comment_sync_states): table is created empty in this same migration so both target uniques build against zero rows with no concurrent writer, and CONCURRENTLY cannot be mixed with the table-creation DDL Prisma wraps in one transaction
CREATE UNIQUE INDEX IF NOT EXISTS "comment_sync_states_comment_id_provider_direction_key" ON "comment_sync_states"("comment_id", "provider", "direction");

-- AddForeignKey
ALTER TABLE "comment_sync_states" ADD CONSTRAINT "comment_sync_states_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "comment_sync_states" ADD CONSTRAINT "comment_sync_states_thread_id_fkey" FOREIGN KEY ("thread_id") REFERENCES "comment_threads"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "comment_sync_states" ADD CONSTRAINT "comment_sync_states_comment_id_fkey" FOREIGN KEY ("comment_id") REFERENCES "comments"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- HAND-WRITTEN 2: a sync row targets exactly one thread or one comment.
ALTER TABLE "comment_sync_states" ADD CONSTRAINT "comment_sync_states_single_target_check" CHECK (num_nonnulls("thread_id", "comment_id") = 1);

-- ISS-11212 data step 1 begin
-- HAND-WRITTEN 1: body_format from the stored body's JSON root, then the thread
-- source for Liveblocks bodies, which carry no `type`. No body is rewritten.
UPDATE "comments" SET "body_format" = 'RICH_V1'
WHERE "body_format" IS NULL AND "body" ->> 'type' = 'doc';

UPDATE "comments" SET "body_format" = 'MARKDOWN'
WHERE "body_format" IS NULL AND "body" ->> 'type' = 'github_markdown';

UPDATE "comments" AS c SET "body_format" = 'LIVEBLOCKS_V1'
FROM "comment_threads" AS t
WHERE c."thread_id" = t."id"
  AND c."body_format" IS NULL
  AND t."source" = 'LIVEBLOCKS';

-- Fail the migration rather than guess a format for a body no rule matches.
DO $$
DECLARE
  unmatched bigint;
BEGIN
  SELECT count(*) INTO unmatched FROM "comments" WHERE "body_format" IS NULL;
  IF unmatched > 0 THEN
    RAISE EXCEPTION 'ISS-11212: % comments rows match no body_format rule', unmatched;
  END IF;
END $$;
-- ISS-11212 data step 1 end

ALTER TABLE "comments" ALTER COLUMN "body_format" SET NOT NULL;

-- ISS-11212 data step 2 begin
-- HAND-WRITTEN 3: native trace anchors move from metadata into the typed column
-- as the v1 envelope, in one statement so no row holds both or neither. A row
-- whose stored anchor is not an object is left as it is; the API reports it.
UPDATE "comment_threads"
SET "anchor" = jsonb_build_object('v', 1, 'kind', 'trace') || ("metadata" -> 'anchor'),
    "anchor_state" = 'ANCHORED',
    "metadata" = "metadata" - 'anchor'
WHERE "source" = 'NATIVE'
  AND "metadata" ->> 'kind' = 'trace_comment'
  AND jsonb_typeof("metadata" -> 'anchor') = 'object';
-- ISS-11212 data step 2 end

-- HAND-WRITTEN 4: in production this migration runs in the new api build's
-- prebuild while the previous bundle still serves (docs/runbooks/deploy-paths.md),
-- and a rollback serves that bundle again. Its Prisma client omits `body_format`
-- on insert and writes a trace anchor into `metadata.anchor`, so each trigger
-- applies the matching rule above to the row it inserts. Neither fires for a
-- writer that fills the new columns. Drop both once no api bundle older than
-- ISS-11212 can serve (ISS-11212, PLN-2120 Step 6 cleanup migration).
CREATE FUNCTION "iss11212_comments_body_format_bridge"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."body" ->> 'type' = 'doc' THEN
    NEW."body_format" := 'RICH_V1';
  ELSIF NEW."body" ->> 'type' = 'github_markdown' THEN
    NEW."body_format" := 'MARKDOWN';
  ELSIF EXISTS (
    SELECT 1 FROM "comment_threads" AS t
     WHERE t."id" = NEW."thread_id" AND t."source" = 'LIVEBLOCKS'
  ) THEN
    NEW."body_format" := 'LIVEBLOCKS_V1';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "comments_iss11212_body_format_bridge"
BEFORE INSERT ON "comments"
FOR EACH ROW WHEN (NEW."body_format" IS NULL)
EXECUTE FUNCTION "iss11212_comments_body_format_bridge"();

CREATE FUNCTION "iss11212_comment_threads_anchor_bridge"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW."anchor" := jsonb_build_object('v', 1, 'kind', 'trace') || (NEW."metadata" -> 'anchor');
  NEW."anchor_state" := 'ANCHORED';
  NEW."metadata" := NEW."metadata" - 'anchor';
  RETURN NEW;
END $$;

CREATE TRIGGER "comment_threads_iss11212_anchor_bridge"
BEFORE INSERT ON "comment_threads"
FOR EACH ROW WHEN (
  NEW."anchor" IS NULL
  AND NEW."source" = 'NATIVE'
  AND NEW."metadata" ->> 'kind' = 'trace_comment'
  AND jsonb_typeof(NEW."metadata" -> 'anchor') = 'object'
)
EXECUTE FUNCTION "iss11212_comment_threads_anchor_bridge"();
